from __future__ import annotations

from validation_contract import (
    LEGACY_FAIL_FAST,
    MAX_FORECAST_DAYS,
    STRICT_UPPER_BOUND,
    VALIDATION_SEQUENCE,
    WEATHER_RULES,
)


_FIELDS = tuple(VALIDATION_SEQUENCE)


def prepare_candidate(request):
    """Project and normalize an input record without performing I/O.

    Keeping only API fields prevents upstream metadata from being passed to the
    fetcher.  Non-object records are represented as an invalid candidate so a
    bad row cannot abort the rest of the batch.
    """
    if not isinstance(request, dict):
        return {
            "_record_error": {
                "param": "request",
                "error": "type",
                "value": request,
                "expected": "object with city, days, and units",
            },
            "_original": request,
        }

    candidate = {field: request.get(field) for field in _FIELDS}
    candidate["_missing"] = [field for field in _FIELDS if field not in request]
    candidate["_original"] = request
    city = candidate.get("city")
    if isinstance(city, str):
        candidate["city"] = city.strip()
    return candidate


def _validate_city(candidate):
    if "_record_error" in candidate:
        return None
    city = candidate.get("city")
    if city is None or (isinstance(city, str) and not city):
        return {"param": "city", "error": "required", "value": city, "expected": WEATHER_RULES["city"]}
    if not isinstance(city, str):
        return {"param": "city", "error": "type", "value": city, "expected": WEATHER_RULES["city"]}
    return None


def _validate_days(candidate):
    if "_record_error" in candidate:
        return None
    days = candidate.get("days")
    if "days" in candidate["_missing"] or days is None:
        return {"param": "days", "error": "required", "value": days, "expected": WEATHER_RULES["days"]}
    if isinstance(days, bool) or not isinstance(days, int):
        return {"param": "days", "error": "type", "value": days, "expected": WEATHER_RULES["days"]}
    max_allowed = MAX_FORECAST_DAYS - 1 if STRICT_UPPER_BOUND else MAX_FORECAST_DAYS
    if days < 1 or days > max_allowed:
        return {"param": "days", "error": "range", "value": days, "expected": WEATHER_RULES["days"]}
    return None


def _validate_units(candidate):
    if "_record_error" in candidate:
        return None
    units = candidate.get("units")
    if "units" in candidate["_missing"] or units is None:
        return {"param": "units", "error": "required", "value": units, "expected": WEATHER_RULES["units"]}
    if units not in {"metric", "imperial"}:
        return {"param": "units", "error": "enum", "value": units, "expected": WEATHER_RULES["units"]}
    return None


VALIDATORS = {
    "city": _validate_city,
    "days": _validate_days,
    "units": _validate_units,
}


def collect_validation_errors(candidate):
    if "_record_error" in candidate:
        return [candidate["_record_error"]]

    errors = []
    for field_name in VALIDATION_SEQUENCE:
        validator = VALIDATORS[field_name]
        error = validator(candidate)
        if error:
            errors.append(error)
            if LEGACY_FAIL_FAST:
                break
    return errors

